%[text] ## Demo1: System Identification using chirp signal
%%
%[text] ### STEP 1: CHIRP EXCITATION
%[text] load settings for the experiment
clear; close all;

Tend = 100; % experiment length [s]
Tcycle = 10; % cycle time of chirp signal [s]
p = 0; % initial phase of chirp [rad]
f0 = 0.5; % min freq of chirp [Hz]
f1 = 4000; % max freq of chirp [Hz]
A = 0.25; % VM-safe feedforward chirp amplitude [A]
trans = 2; % number of transient periods
Jn = 7.1e-5; % student-tunable nominal inertia [A/(rad/s^2)], (Jmotor+Jload)/(ratedTorque/ratedCurrent)
Dn = 5.325e-4; % student-tunable nominal damping [A/(rad/s)], (Dmotor+Dload)/(ratedTorque/ratedCurrent)
Ndelay = 4; % student-tunable delay step of plant [samples]

save_results = true;
require_logger_records = true;
hold_margin_s = 1.0;

scenario = experiment.scenario.exp01( ...
  "Tend", Tend, "Tcycle", Tcycle, "initial_phase", p, ...
  "f0", f0, "f1", f1, "amplitude_A", A, ...
  "transient_cycles", trans, "Jn", Jn, "Dn", Dn, ...
  "sample_delay", Ndelay, "hold_margin_s", hold_margin_s, ...
  "save_results", save_results, ...
  "require_logger_records", require_logger_records);
Ts = scenario.Ts;
chirp = scenario.chirp;
applied_peak_A = chirp.applied_peak_A;
applied_mean_A = chirp.applied_mean_A;
scenario_table = table( ...
  Ts, Tend, Tcycle, f0, f1, A, applied_peak_A, applied_mean_A, ...
  Jn, Dn, Ndelay, ...
  VariableNames=["Ts_s", "duration_s", "cycle_s", "f0_Hz", ...
    "f1_Hz", "requestedAmplitude_A", "appliedPeak_A", "appliedMean_A", ...
    "Jn", "Dn", "delay_samples"]);
display(scenario_table); %[output:04328327]
%%
%[text] design excitation signal
N = chirp.sample_count;
t = chirp.t;
u = chirp.signal;

figure("Name", "Chirp Excitation", "Color", "w"); %[output:09ab5eed]
plot(t, u, "-", "LineWidth", 1.0); %[output:09ab5eed]
grid on; %[output:09ab5eed]
xlabel("Time [s]"); %[output:09ab5eed]
ylabel("Feedforward current [A]"); %[output:09ab5eed]
title("Open-loop chirp excitation"); %[output:09ab5eed]
%%
%[text] execute the VirtualMotor experiment through the shared workflow
workflow = experiment.workflow.run_exp01(scenario);
run_out = workflow.run;
logger_bin = workflow.logger;
run_summary = table( ...
  logical(run_out.host.done), logical(run_out.host.timed_out), ...
  string(run_out.host.stop_reason), double(logger_bin.record_count), ...
  string(logger_bin.file_path), ...
  VariableNames=["done", "timedOut", "stopReason", ...
    "loggerRecords", "loggerFile"]);
display(run_summary); %[output:30abed6b]

%%
%[text] Numeric experiment and fitted-plant artifacts are saved by the workflow.
completed_at_utc = string(datetime("now", "TimeZone", "UTC", ...
  "Format", "yyyy-MM-dd'T'HH:mm:ss.SSSXXX"));
artifact_summary = table( ...
  string(workflow.artifacts.chirp_result), string(workflow.artifacts.plant), ...
  completed_at_utc, ...
  VariableNames=["chirpResult", "plantModel", "completedAtUtc"]);
display(artifact_summary); %[output:31078b94]
%%
%[text] ### STEP 2: TIME TREATMENT
%[text] remove transient periods
input = workflow.signals.analysis_input;
loadvel = workflow.signals.load_velocity;
motorvel = workflow.signals.motor_velocity;
%%
%[text] ### STEP 3: NON-PARAMETRIC ESTIMATION
%[text] fft data and vizualize in freq domain position data
Pd_vel_load = workflow.plant.Pd_vel_load;
Pd_vel_motor = workflow.plant.Pd_vel_motor;
%%
%[text] check coherence (good if close to 0dB)
figure("Name", "Load-side coherence", "Color", "w"); %[output:4ec3973c]
semilogx(workflow.metrics.frequency_hz, workflow.metrics.load_coherence); %[output:4ec3973c]
ax = gca; ax.XScale = 'log'; %[output:4ec3973c]
title("load-side coherence"); %[output:4ec3973c]

figure("Name", "Motor-side coherence", "Color", "w"); %[output:127980de]
semilogx(workflow.metrics.frequency_hz, workflow.metrics.motor_coherence); %[output:127980de]
ax = gca; ax.XScale = 'log'; %[output:127980de]
title("motor-side coherence"); %[output:127980de]
%%
%[text] ### Manual data fitting of system $P${"editStyle":"visual"}
%[text] True system: $P=\\frac{1}{{\\textrm{Js}}^2 +\\textrm{Ds}}${"editStyle":"visual"}
%[text] Nominal system: $P\_n =\\frac{1}{{J\_n s}^2 +D\_n s}${"editStyle":"visual"}
%[text] design $J\_n${"editStyle":"visual"} and $D\_n${"editStyle":"visual"} so $P\_n${"editStyle":"visual"} becomes close to $P${"editStyle":"visual"}.
Pd_load = workflow.plant.Pd_load;
Pd_motor = workflow.plant.Pd_motor;
Pdn = workflow.plant.Pdn;

bop_ = bodeoptions("cstprefs");
bop_.FreqUnits = 'Hz';
bop_.PhaseWrapping = 'on';
bop_.XLimMode = 'manual';
bop_.XLim = {[1, 1/2/Ts]};
bop_.Grid = 'off';
bop_.YLim = {[-80, 80]; [-180, 180]};
figure("Name", "Manual plant fitting", "Color", "w"); %[output:7a92a4a3]
bode(Pd_load, Pd_motor, Pdn, bop_); %[output:7a92a4a3]
legend(["$P_{\mathrm{load}}$", "$P_{\mathrm{motor}}$", "$P_{n}$"], "Interpreter", "latex"); %[output:7a92a4a3]
%%
%[text] save fitting data
%[text] load-side position will be the main objective of control for demo2 to demo4
Pd = workflow.plant.Pd;
quality_summary = table( ...
  workflow.metrics.minimum_load_coherence_1_500_hz, ...
  workflow.metrics.minimum_motor_coherence_1_500_hz, ...
  workflow.metrics.nonzero_motion, ...
  VariableNames=["minLoadCoherence_1_500Hz", ...
    "minMotorCoherence_1_500Hz", "nonzeroMotion"]);
display(quality_summary); %[output:4f3ac503]



